"use client";

import React, { useCallback, useEffect, useRef, useState } from "react";
import { ScanRecipe } from "./CameraScan";
import ReportContent from "./ReportContent";
import RecipeDetail from "./RecipeDetail";
import { parseIngredient } from "./recipe-utils";
import "./hub.css";

type Item = { id: string; kind: string; data: Record<string, any>; version: number; createdAt: string; updatedAt: string };
type HouseholdFeed = { id: string; workflow: string; sourceId: string; title: string; summary?: string; body?: string; sourceLink?: string; observedAt: string; lastSuccess?: string; runStatus: string; version: number; createdAt?: string; updatedAt?: string };
type HubState = { records: Item[]; householdFeed?: HouseholdFeed[]; serverTime?: string; permissions?: { admin: boolean }; integrations?: Record<string, any> };
type ICloudStatus = { configured: boolean; username?: string; calendars: Array<{ id: string; displayName: string; color?: string }>; selectedCalendarIds: string[]; lastSuccess?: string; lastAttempt?: string; status: "unconfigured" | "configured" | "ready" | "error"; error?: string };
type View = "overview" | "calendar" | "lists" | "reminders" | "recipes" | "meals" | "sources" | "settings";
type Editor = { kind: string; item?: Item; initial?: Record<string, any> } | null;
const TZ = "Europe/London";
const COLOURS = ["#78d3ef", "#e6b5d2", "#e6ca84", "#9bd2b2", "#b5a4ec"];
const KIND_LABEL: Record<string, string> = { calendar: "event", shopping: "shopping item", reminder: "family task", recipe: "recipe", meal: "meal", profile: "family profile", source: "source" };
const VIEWS: Array<{ id: View; label: string; icon: string }> = [
  { id: "overview", label: "Home", icon: "orbit" }, { id: "calendar", label: "Calendar", icon: "calendar" },
  { id: "lists", label: "Lists", icon: "check" }, { id: "reminders", label: "Family tasks", icon: "check" },
  { id: "recipes", label: "Recipes", icon: "book" }, { id: "meals", label: "Meal plan", icon: "meal" },
  { id: "sources", label: "Sources", icon: "network" },
];
const UNCONFIGURED_SOURCES: Item[] = [
    { id: "icloud", kind: "source", data: { title: "iCloud calendars", detail: "Site connection required", runStatus: "awaiting_access" } },
    { id: "news", kind: "source", data: { title: "Morning briefing", detail: "Existing task · writer unverified", runStatus: "awaiting_access" } },
    { id: "events", kind: "source", data: { title: "UK events", detail: "Existing task · writer unverified", runStatus: "awaiting_access" } },
    { id: "holidays", kind: "source", data: { title: "Travel deals", detail: "Existing task · writer unverified", runStatus: "awaiting_access" } },
    { id: "weekly", kind: "source", data: { title: "Weekly dashboard", detail: "Paused · remains separate", runStatus: "paused" } },
    { id: "transport", kind: "source", data: { title: "Transport", detail: "Local task · connection unresolved", runStatus: "awaiting_access" } },
    { id: "email", kind: "source", data: { title: "Email organisation", detail: "Local task · connection unresolved", runStatus: "awaiting_access" } },
  ].map(s => ({ ...s, version: 0, createdAt: "", updatedAt: "" }));

const ICONS: Record<string, React.ReactNode> = {
  orbit: <><circle cx="12" cy="12" r="3"/><ellipse cx="12" cy="12" rx="10" ry="5" transform="rotate(-35 12 12)"/><path d="M18 4l2 2"/></>,
  calendar: <><rect x="3" y="5" width="18" height="16" rx="3"/><path d="M7 3v4m10-4v4M3 11h18m-12 4h2m4 0h2m-8 3h2"/></>,
  check: <><rect x="3" y="3" width="18" height="18" rx="4"/><path d="m7 12 3 3 7-7"/></>,
  bell: <><path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/></>,
  book: <><path d="M12 5v16M3 4c4-1 7 0 9 2 2-2 5-3 9-2v15c-4-1-7 0-9 2-2-2-5-3-9-2Z"/></>,
  meal: <><path d="M4 3v7c0 3 5 3 5 0V3M6.5 3v18M18 3c-5 2-5 10 0 10V3Zm0 10v8"/></>,
  network: <><circle cx="12" cy="12" r="3"/><circle cx="4" cy="4" r="2"/><circle cx="20" cy="4" r="2"/><circle cx="4" cy="20" r="2"/><circle cx="20" cy="20" r="2"/><path d="m6 6 4 4m4 4 4 4M6 18l4-4m4-4 4-4"/></>,
  plus: <path d="M12 5v14M5 12h14"/>, close: <path d="m6 6 12 12M6 18 18 6"/>,
  edit: <><path d="m15 4 5 5M4 20l5-1L21 7l-5-5L4 14Z"/></>,
  arrow: <path d="m9 5 7 7-7 7"/>, back: <path d="m15 5-7 7 7 7"/>,
  settings: <><path d="M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1Z"/><circle cx="12" cy="12" r="3"/></>,
  display: <><rect x="2" y="3" width="20" height="14" rx="2"/><path d="M8 21h8m-4-4v4"/></>,
  camera: <><path d="M3 7h4l2-3h6l2 3h4v14H3Z"/><circle cx="12" cy="13" r="4"/></>,
  search: <><circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/></>,
  download: <><path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/></>,
  refresh: <><path d="M20 8a9 9 0 1 0 0 9M20 3v6h-6"/></>,
  lock: <><rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V6a4 4 0 0 1 8 0v4m-4 5v2"/></>,
};
function Icon({ name, size = 18 }: { name: string; size?: number }) { return <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">{ICONS[name] || ICONS.orbit}</svg>; }
function dateKey(date: Date | string = new Date()) { return new Intl.DateTimeFormat("en-CA", { timeZone: TZ, year: "numeric", month: "2-digit", day: "2-digit" }).format(new Date(date)); }
function addDays(day: string, n: number) { const d = new Date(`${day}T12:00:00Z`); d.setUTCDate(d.getUTCDate() + n); return d.toISOString().slice(0, 10); }
function shiftMonth(day: string, delta: number) { const d = new Date(`${day}T12:00:00Z`); const original = d.getUTCDate(); d.setUTCDate(1); d.setUTCMonth(d.getUTCMonth() + delta); const max = new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth() + 1, 0)).getUTCDate(); d.setUTCDate(Math.min(original, max)); return d.toISOString().slice(0, 10); }
function weekStart(day: string) { const n = new Date(`${day}T12:00:00Z`).getUTCDay(); return addDays(day, -(n === 0 ? 6 : n - 1)); }
function formatDate(day: string, options: Intl.DateTimeFormatOptions = { weekday: "short", day: "numeric", month: "short" }) { return new Intl.DateTimeFormat("en-GB", { ...options, timeZone: TZ }).format(new Date(day.length === 10 ? `${day}T12:00:00Z` : day)); }
function time(iso: string) { return new Intl.DateTimeFormat("en-GB", { timeZone: TZ, hour: "2-digit", minute: "2-digit" }).format(new Date(iso)); }
function localInput(iso?: string) { if (!iso) return ""; const p = new Intl.DateTimeFormat("en-GB", { timeZone: TZ, year: "numeric", month: "2-digit", day: "2-digit", hour: "2-digit", minute: "2-digit", hourCycle: "h23" }).formatToParts(new Date(iso)); const get = (key: string) => p.find(x => x.type === key)?.value; return `${get("year")}-${get("month")}-${get("day")}T${get("hour")}:${get("minute")}`; }
function londonISO(value: string) { const wanted = value.length === 10 ? `${value}T00:00` : value; const utc = Date.parse(`${wanted}:00Z`); let guess = utc; for (let i = 0; i < 3; i++) { const shown = Date.parse(`${localInput(new Date(guess).toISOString())}:00Z`); guess += utc - shown; } const result = new Date(guess).toISOString(); if (localInput(result) !== wanted) throw new Error("That time does not exist during the London daylight-saving change. Choose another time."); return result; }
function age(iso?: string, now = Date.now()) { if (!iso) return "Never checked"; const minutes = Math.max(0, Math.floor((now - Date.parse(iso)) / 60000)); return minutes < 1 ? "Just now" : minutes < 60 ? `${minutes}m ago` : minutes < 1440 ? `${Math.floor(minutes / 60)}h ago` : `${Math.floor(minutes / 1440)}d ago`; }
function freshness(source: Pick<Item, "data">, now: number) { const last = source.data.lastSuccess; if (!last) return "grey"; const elapsed = now - Date.parse(last); if (!Number.isFinite(elapsed) || elapsed < -300000) return "grey"; return elapsed <= 3600000 ? "green" : elapsed <= 86400000 ? "yellow" : "red"; }
function ingredientsText(ingredients: any[] = []) { return ingredients.map(x => [x.amount ?? "", x.unit || "", x.name].filter(x => x !== "").join(" ")).join("\n"); }
function parseIngredients(text: string) { return text.split("\n").map(x => x.trim()).filter(Boolean).map(parseIngredient); }
function safeLink(value?: string) { if (!value) return undefined; try { const u = new URL(value); return ["https:", "http:"].includes(u.protocol) ? u.href : undefined; } catch { return undefined; } }

export default function Hub() {
  const [hub, setHub] = useState<HubState>({ records: [] });
  const [view, setView] = useState<View>("overview");
  const [wall, setWall] = useState(false);
  const [viewReady, setViewReady] = useState(false);
  const [now, setNow] = useState(new Date());
  const [loading, setLoading] = useState(true);
  const [saveState, setSaveState] = useState("saved");
  const [error, setError] = useState("");
  const [toast, setToast] = useState("");
  const [undoRoutine, setUndoRoutine] = useState<{ item: Item; data: Record<string, any> } | null>(null);
  const [editor, setEditor] = useState<Editor>(null);
  const [cooking, setCooking] = useState<Item | null>(null);
  const [scan, setScan] = useState(false);
  const [onlineImport, setOnlineImport] = useState(false);
  const [recipeFilter, setRecipeFilter] = useState("all");
  const [selectedDay, setSelectedDay] = useState(dateKey());
  const [calendarMode, setCalendarMode] = useState("week");
  const [calendarFilter, setCalendarFilter] = useState("");
  const [personFilter, setPersonFilter] = useState("");
  const [taskFilter, setTaskFilter] = useState("");
  const [taskLayout, setTaskLayout] = useState("board");
  const [listName, setListName] = useState("Groceries");
  const [search, setSearch] = useState("");
  const [sourceId, setSourceId] = useState("");
  const [ingredientMeal, setIngredientMeal] = useState<Item | null>(null);
  const [excluded, setExcluded] = useState<string[]>([]);
  const [importList, setImportList] = useState("Groceries");
  const [importServings, setImportServings] = useState(4);

  const writeBusy = useRef(false);
  const today = dateKey(now);
  const records = hub.records;
  const byKind = useCallback((kind: string) => records.filter(r => r.kind === kind), [records]);
  const profiles = byKind("profile");
  const recipes = byKind("recipe");
  const meals = byKind("meal");
  const sources = byKind("source");
  const shopping = byKind("shopping");
  const reminders = byKind("reminder");
  const allEvents = byKind("calendar");
  const calendarSources = Array.from(new Map(allEvents.filter(r => r.data.calendarId).map(r => [r.data.calendarId, { id: r.data.calendarId, title: r.data.calendarTitle || "Apple Calendar", color: r.data.color }])).values());
  const icloud = hub.integrations?.icloud || { configured: false, status: "unconfigured" };
  const icloudSignal = icloud.lastSuccess ? freshness({ data: { lastSuccess: icloud.lastSuccess } }, now.getTime()) : "grey";
  const icloudLabel = icloud.status === "error" ? "iCloud sync needs attention · last data retained" : icloud.lastSuccess ? `iCloud synced ${age(icloud.lastSuccess, now.getTime())}` : icloud.configured ? "iCloud account connected · calendar sync pending" : "iCloud calendar awaiting connection";
  const events = allEvents.filter(r => (!personFilter || r.data.person === personFilter) && (!calendarFilter || r.data.calendarId === calendarFilter || (calendarFilter === "__manual" && r.data.origin !== "icloud"))).sort((a, b) => a.data.startAt.localeCompare(b.data.startAt));
  const lists = Array.from(new Set(["Groceries", listName, ...shopping.map(r => r.data.listName || "Groceries")])).sort();
  const personColour = (name?: string) => profiles.find(p => p.data.name === name)?.data.color || "#78d3ef";
  const eventsOn = (day: string) => events.filter(e => { const start = e.data.startAt.length === 10 ? e.data.startAt : dateKey(e.data.startAt); const end = e.data.endAt.length === 10 ? e.data.endAt : dateKey(e.data.endAt); if (e.data.allDay) return start <= day && (end > day || (end === start && day === start)); return start <= day && end >= day && (end !== day || time(e.data.endAt) !== "00:00" || start === day); });
  const load = useCallback(async (silent = false) => {
    try { const res = await fetch("/api/state", { cache: "no-store", credentials: "same-origin" }); const data: any = await res.json(); if (!res.ok) throw new Error(data.error?.message || data.error || "The household could not be loaded."); setHub(data); if (!writeBusy.current) setSaveState("saved"); if (!silent) setError(""); return true; }
    catch (e: any) { setSaveState(typeof navigator !== "undefined" && !navigator.onLine ? "offline" : "error"); if (!silent) setError(e.message || "Connection failed. Your changes have not been saved."); return false; }
    finally { setLoading(false); }
  }, []);
  useEffect(() => { const initial = new URLSearchParams(window.location.search); setWall(initial.get("wall") === "1"); setViewReady(true); const start = initial.get("view"); if (VIEWS.some(v => v.id === start) || start === "settings") setView(start as View); void load(); const tick = setInterval(() => setNow(new Date()), 1000); const poll = setInterval(() => { if (document.visibilityState === "visible" && !writeBusy.current) void load(true); }, 15000); const online = () => void load(); const offline = () => setSaveState("offline"); const visible = () => { if (document.visibilityState === "visible") void load(true); }; window.addEventListener("online", online); window.addEventListener("offline", offline); document.addEventListener("visibilitychange", visible); return () => { clearInterval(tick); clearInterval(poll); window.removeEventListener("online", online); window.removeEventListener("offline", offline); document.removeEventListener("visibilitychange", visible); }; }, [load]);
  useEffect(() => { if (!toast) return; const timeout = setTimeout(() => { setToast(""); setUndoRoutine(null); }, undoRoutine ? 12000 : 4500); return () => clearTimeout(timeout); }, [toast, undoRoutine]);
  const mutate = async (path: string, method: string, body: any, key?: string) => {
    if (writeBusy.current) throw new Error("Please wait for the current change to save.");
    writeBusy.current = true; setSaveState("saving"); setError("");
    try { const res = await fetch(path, { method, credentials: "same-origin", headers: { "Content-Type": "application/json", ...(method === "POST" ? { "Idempotency-Key": key || crypto.randomUUID() } : {}) }, body: JSON.stringify(body) }); const data: any = await res.json(); if (!res.ok) { if (res.status === 409) { await load(true); throw new Error("Another device changed this item. The latest version is loaded; please try your change again."); } throw new Error(data.error?.message || data.error || "The change could not be saved."); } const refreshed = await load(true); if (refreshed) setSaveState("saved"); return data; }
    catch (e: any) { setSaveState(!navigator.onLine ? "offline" : "error"); setError(e.message || "Save failed. Your change has not synchronised."); throw e; }
    finally { writeBusy.current = false; }
  };
  const add = (kind: string, initial: Record<string, any> = {}) => setEditor({ kind, initial });
  const patch = async (item: Item, data: Record<string, any>) => { try { const result = await mutate(`/api/items/${encodeURIComponent(item.id)}`, "PATCH", { version: item.version, data }); if (item.kind === "reminder" && data.done === true && item.data.repeat !== "none" && item.data.dueAt) { setUndoRoutine({ item: { ...item, version: result.record.version }, data: { ...item.data, lastCompletedAt: item.data.lastCompletedAt || null } }); setToast("Routine completed. The next due date is ready."); } } catch {} };
  const remove = async (item: Item) => { try { await mutate(`/api/items/${encodeURIComponent(item.id)}`, "DELETE", { version: item.version }); setEditor(null); setCooking(null); setToast("Removed from the household."); } catch {} };
  const navigate = (next: View) => { setView(next); setSearch(""); window.scrollTo({ top: 0, behavior: "smooth" }); };
  const toggleWall = () => { const value = !wall; setWall(value); const url = new URL(window.location.href); value ? url.searchParams.set("wall", "1") : url.searchParams.delete("wall"); window.history.replaceState({}, "", url); };
  const tonight = meals.find(m => m.data.day === today && m.data.slot === "dinner");
  const due = reminders.filter(r => !r.data.done).sort((a, b) => (a.data.dueAt || "9999").localeCompare(b.data.dueAt || "9999"));
  const upcoming = events.filter(e => Date.parse(e.data.endAt) >= now.getTime() && dateKey(e.data.startAt) <= addDays(today, 7));
  const startIngredients = (meal: Item, portions?: number) => { setIngredientMeal(meal); setExcluded([]); setImportList("Groceries"); setImportServings(portions || meal.data.servings || mealRecipe(meal)?.servings || 4); };
  const mealRecipe = (meal?: Item | null) => meal?.kind === "recipe" ? meal.data : meal?.data.recipeSnapshot || recipes.find(r => r.id === meal?.data.recipeId)?.data;
  const ingredientImport = async () => { if (!ingredientMeal) return; try { const input = JSON.stringify({ meal: ingredientMeal.id, recipe: mealRecipe(ingredientMeal), servings: importServings, list: importList, excluded: [...excluded].sort() }); const hash = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(input)); const key = "meal_" + [...new Uint8Array(hash)].map(n => n.toString(16).padStart(2, "0")).join(""); await mutate(`/api/${ingredientMeal.kind === "recipe" ? "recipes" : "meals"}/${encodeURIComponent(ingredientMeal.id)}/ingredients`, "POST", { listName: importList, servings: importServings, excludedIngredientNames: excluded }, key); setIngredientMeal(null); setToast("Ingredients added to your shared list."); } catch {} };
  const listRows = (items: Item[], compact = false) => <div className="task-list">{items.map(item => <div className={`check-row ${item.data.done ? "completed" : ""}`} key={item.id}><button className={`check-button ${item.data.done ? "checked" : ""}`} role="checkbox" aria-checked={!!item.data.done} aria-label={`${item.data.done ? "Restore" : "Complete"} ${item.data.title}`} disabled={saveState === "saving"} onClick={() => void patch(item, { done: !item.data.done })}>{item.data.done && <Icon name="check" size={17}/>}</button><button className="item-copy" onClick={() => setEditor({ kind: item.kind, item })}><span className="item-title">{item.data.title}</span><span className="item-meta">{item.kind === "shopping" ? [item.data.quantity, item.data.category].filter(Boolean).join(" · ") : [item.data.assignedTo, item.data.dueAt ? `${Date.parse(item.data.dueAt) < now.getTime() && !item.data.done ? "Overdue · " : ""}${formatDate(item.data.dueAt)}` : "No due date", item.data.repeat && item.data.repeat !== "none" ? item.data.repeat : ""].filter(Boolean).join(" · ")}</span></button>{!compact && <button className="icon-button" aria-label={`Edit ${item.data.title}`} onClick={() => setEditor({ kind: item.kind, item })}><Icon name="edit" size={15}/></button>}</div>)}</div>;
  const renderEvent = (item: Item) => <button className="agenda-item" key={item.id} onClick={() => setEditor({ kind: "calendar", item })}><span className="event-time">{item.data.allDay ? "ALL DAY" : time(item.data.startAt)}</span><span className="event-line" style={{ borderColor: (item.data.color || personColour(item.data.person)) }}><strong>{item.data.title}</strong><span>{[item.data.person, item.data.calendarTitle, item.data.location, item.data.status === "tentative" ? "Tentative" : "", item.data.origin === "icloud" ? "Apple · read-only" : "Hub event"].filter(Boolean).join(" · ")}</span></span><Icon name="arrow" size={14}/></button>;
  const empty = (text: string, action?: string, click?: () => void) => <div className="empty-state"><span className="empty-star">✧</span><p>{text}</p>{action && <button className="panel-link" onClick={click}>{action} <Icon name="plus" size={13}/></button>}</div>;
  const miniSources = sources.slice(0, 4);
  const householdFeed = hub.householdFeed || [];
  const newsFeed = householdFeed.filter(f => /news|briefing/i.test(`${f.workflow} ${f.sourceId} ${f.title}`)).sort((a, b) => b.observedAt.localeCompare(a.observedAt))[0];
  const weeklyFeed = householdFeed.filter(f => /(?:weekly|daily|ryan).*dashboard|dashboard.*(?:weekly|daily|ryan)/i.test(`${f.workflow} ${f.sourceId} ${f.title}`)).sort((a, b) => b.observedAt.localeCompare(a.observedAt))[0];
  const travelFeed = householdFeed.filter(f => /travel|holiday/i.test(`${f.workflow} ${f.sourceId} ${f.title}`)).sort((a, b) => b.observedAt.localeCompare(a.observedAt))[0];
  const shownTasks = reminders.filter(r => !taskFilter || (taskFilter === "__unassigned" ? !r.data.assignedTo : r.data.assignedTo === taskFilter));
  const shownOpenTasks = shownTasks.filter(r => !r.data.done).sort((a, b) => (a.data.dueAt || "9999").localeCompare(b.data.dueAt || "9999"));
  const taskPeople = Array.from(new Set([...profiles.map(p => p.data.name), ...reminders.map(r => r.data.assignedTo).filter(Boolean), ""]));

  return <div className={`bird-app ${wall ? "wall-mode" : ""}`}>
    <header className="app-header"><button className="brand" onClick={() => navigate("overview")} aria-label="Bird Family Hub home"><span className="brand-mark"><svg viewBox="0 0 44 44" fill="none" aria-hidden="true"><path d="M5 20c7-8 12-7 17 2 5-9 10-10 17-2M11 15c4-4 8-3 11 2 3-5 7-6 11-2" stroke="currentColor" strokeWidth="2"/><circle cx="22" cy="30" r="2" fill="currentColor"/><path d="M22 2v5M22 37v5M2 22h5m30 0h5" stroke="currentColor" opacity=".4"/></svg></span><span className="brand-copy"><span className="brand-title">BIRD<span>FAMILY HUB</span></span><span className="brand-caption">A LITTLE MORE IN SYNC</span></span></button><div className="header-right"><div className="live-clock"><strong suppressHydrationWarning>{time(now.toISOString())}</strong><span>{formatDate(today, { weekday: "short", day: "numeric", month: "short" })} · London</span></div><span className="privacy-pill"><Icon name="lock" size={12}/> Private household</span><button className={`icon-button ${wall ? "active" : ""}`} onClick={toggleWall} aria-label={wall ? "Exit wall display" : "Open wall display"} title={wall ? "Exit wall display" : "Wall display"}><Icon name="display"/></button><button className="icon-button" onClick={() => navigate("settings")} aria-label="Household settings"><Icon name="settings"/></button></div></header>
    <nav className="main-nav" aria-label="Main navigation">{VIEWS.map(v => <button className={`nav-button ${view === v.id ? "active" : ""}`} key={v.id} onClick={() => navigate(v.id)} aria-current={view === v.id ? "page" : undefined}><Icon name={v.icon}/><span>{v.label}</span></button>)}<div className={`status-bar ${saveState}`} role="status"><span className="status-dot"/>{saveState === "saving" ? "Saving…" : saveState === "offline" ? "Offline · changes cannot sync" : saveState === "error" ? "Connection needs attention" : loading ? "Connecting…" : "Shared data connected"}</div></nav>
    <main className="main-content">
      {(saveState === "offline" || saveState === "error") && !error && <div className="notice warning" role="status">{saveState === "offline" ? "You’re offline. Showing the last loaded household data; changes cannot synchronise until you reconnect." : "The household connection needs attention. Showing the last loaded data."}<button className="button ghost small" style={{ marginLeft: 12 }} onClick={() => void load()}>Retry</button></div>}
      {error && <div className="notice warning" role="alert"><span>{String(error)}</span><button className="button small ghost" onClick={() => void load()}>Retry</button></div>}
      {wall && <div className="wall-notice">Wall display · family records only. This display uses your signed-in session; wall mode does not limit its account access.</div>}
      {loading ? <div className="loading-shell"><div className="loading-orbit"/><p>Connecting your household…</p></div> : <>
      {view === "overview" && <>
        <div className="view-heading"><div><p className="eyebrow">YOUR HOUSEHOLD, AT A GLANCE</p><h1>Life, in a little more orbit<span className="heading-dot">.</span></h1><p className="subtle">A shared space for the days, plans and little things that matter.</p></div><button className="button primary" onClick={() => add("calendar", { day: today })}><Icon name="plus"/> Add something</button></div>
        <div className="overview-grid">
          <section className="panel calendar-preview"><div className="panel-header"><div><span className="panel-kicker">01 / THE HORIZON</span><h2 className="panel-title">Coming into view</h2></div><button className="icon-button" onClick={() => navigate("calendar")} aria-label="Open calendar"><Icon name="arrow"/></button></div><div className="day-strip">{Array.from({ length: 7 }, (_, i) => addDays(today, i)).map(day => <button className={`day-chip ${selectedDay === day ? "selected" : ""}`} key={day} onClick={() => setSelectedDay(day)}><span className="day-name">{formatDate(day, { weekday: "short" })}</span><span className="day-number">{day.slice(8)}</span><span className={`day-dot ${eventsOn(day).length ? "has-events" : ""}`}/></button>)}</div><div className="section-label">{selectedDay === today ? "TODAY" : formatDate(selectedDay).toUpperCase()}</div><div className="agenda-list">{eventsOn(selectedDay).slice(0, 4).map(renderEvent)}{!eventsOn(selectedDay).length && empty("No events loaded for this day.", "Add an event", () => add("calendar", { day: selectedDay }))}</div><button className="connection-line source-row" onClick={() => { const source = sources.find(s => s.data.adapter === "icloud" || /icloud/i.test(s.data.title)); setSourceId(source?.id || "icloud"); navigate("sources"); }}><span className={`status-dot ${icloudSignal}`}/><span>{icloudLabel}</span></button><button className="panel-link" onClick={() => navigate("calendar")}>Open the full calendar <Icon name="arrow" size={14}/></button></section>
          <section className="core-panel" aria-label="Family hub"><div className="core-date">{formatDate(today, { weekday: "long", day: "numeric", month: "long" }).toUpperCase()}</div><div className="orbit-shell"><div className="orbit-ring ring-1"/><div className="orbit-ring ring-2"/><div className="orbit-ring ring-3"/><span className="orbit-particle p1"/><span className="orbit-particle p2"/><span className="orbit-particle p3"/><div className="orbit-core"><svg viewBox="0 0 44 44" fill="none" aria-hidden="true"><path d="M3 19c8-7 13-6 19 4 6-10 11-11 19-4M10 13c5-3 9-1 12 4 3-5 7-7 12-4" stroke="currentColor" strokeWidth="1.7"/></svg><span className="core-monogram">BIRD</span><span className="core-caption">FAMILY NETWORK</span></div></div><div className="core-clock" suppressHydrationWarning>{time(now.toISOString())}<span suppressHydrationWarning>{new Intl.DateTimeFormat("en-GB", { timeZone: TZ, second: "2-digit" }).format(now)}</span></div><div className="core-copy"><span className="status-dot green"/> Your little world, connected</div><div className="quick-actions"><button className="quick-action" onClick={() => add("shopping", { listName })}><Icon name="plus"/><span className="quick-label">Add to list</span></button><button className="quick-action" onClick={() => add("reminder")}><Icon name="bell"/><span className="quick-label">Add a task</span></button><button className="quick-action" onClick={() => { navigate("recipes"); setScan(true); }}><Icon name="camera"/><span className="quick-label">Scan recipe</span></button></div></section>
          <section className="panel"><div className="panel-header"><div><span className="panel-kicker">02 / ON OUR RADAR</span><h2 className="panel-title">Family tasks</h2></div><button className="icon-button" aria-label="Add family task" onClick={() => add("reminder")}><Icon name="plus"/></button></div>{due.length ? listRows(due.slice(0, 4), true) : empty("A little breathing room. No open reminders.", "Add a family task", () => add("reminder"))}<div className="stat-row"><div><span className="stat-value">{due.length.toString().padStart(2, "0")}</span><span className="stat-label">ON THE RADAR</span></div><div><span className="stat-value">{upcoming.length.toString().padStart(2, "0")}</span><span className="stat-label">UPCOMING EVENTS</span></div></div><button className="panel-link" onClick={() => navigate("reminders")}>See family tasks <Icon name="arrow" size={14}/></button></section>
        </div>
        <div className="household-feed"><BriefingCard kind="news" feed={newsFeed} now={now.getTime()} today={today} onSource={() => { const source = sources.find(s => s.data.sourceId === newsFeed?.sourceId || /news|briefing/i.test(s.data.title)); if (source) setSourceId(source.id); navigate("sources"); }}/><BriefingCard kind="travel" feed={travelFeed} now={now.getTime()} today={today} onSource={() => { const source = sources.find(s => s.data.sourceId === travelFeed?.sourceId || /travel|holiday/i.test(s.data.title)); if (source) setSourceId(source.id); navigate("sources"); }}/><BriefingCard kind="weekly" feed={weeklyFeed} now={now.getTime()} today={today} onSource={() => { const source = sources.find(s => s.data.sourceId === weeklyFeed?.sourceId || /weekly.*dashboard/i.test(s.data.title)); if (source) setSourceId(source.id); navigate("sources"); }}/></div>
        {viewReady && !wall && hub.permissions?.admin && !weeklyFeed && <OwnerDashboardPreview/>}
        <div className="overview-bottom"><section className="panel"><div className="panel-header"><div><span className="panel-kicker">03 / PICK IT UP</span><h2 className="panel-title">The shopping list <span className="count-pill">{shopping.filter(r => !r.data.done).length}</span></h2></div><button className="icon-button" aria-label="Add shopping item" onClick={() => add("shopping", { listName })}><Icon name="plus"/></button></div>{shopping.some(r => !r.data.done) ? listRows(shopping.filter(r => !r.data.done).slice(0, 3), true) : empty("Nothing on the list. Yet.", "Add your first item", () => add("shopping", { listName }))}<button className="panel-link" onClick={() => navigate("lists")}>Take the list with you <Icon name="arrow" size={14}/></button></section><section className="panel meal-card"><div className="panel-header"><div><span className="panel-kicker">04 / AROUND THE TABLE</span><h2 className="panel-title">Tonight, together</h2></div><Icon name="meal" size={24}/></div><span className="meal-tag">{tonight ? "DINNER IS PLANNED" : "A BLANK CANVAS"}</span><h3 className="meal-title">{tonight?.data.title || mealRecipe(tonight)?.title || "What’s for dinner?"}</h3><p className="subtle">{tonight ? `${tonight.data.servings || mealRecipe(tonight)?.servings || "—"} portions · ${mealRecipe(tonight) ? "From your recipe collection" : "Your family’s plan"}` : "Give the evening one less decision. Pick a recipe or keep it simple."}</p><button className="button ghost" onClick={() => tonight ? setEditor({ kind: "meal", item: tonight }) : add("meal", { day: today, slot: "dinner" })}>{tonight ? "View tonight’s plan" : "Plan tonight"}<Icon name="arrow" size={15}/></button></section><section className="panel source-mini"><div className="panel-header"><div><span className="panel-kicker">05 / SIGNAL CHECK</span><h2 className="panel-title">Behind the scenes</h2></div><button className="icon-button" aria-label="Explore source network" onClick={() => navigate("sources")}><Icon name="network"/></button></div>{miniSources.length ? miniSources.map(source => <button className="connection-line source-row" key={source.id} onClick={() => { setSourceId(source.id); navigate("sources"); }}><span className={`status-dot ${freshness(source, now.getTime())}`}/><span>{source.data.title}</span><span className="item-meta">{age(source.data.lastSuccess, now.getTime())}</span></button>) : <><div className="connection-line"><span className="status-dot green"/><span>Household records</span><span className="item-meta">Connected</span></div><div className="connection-line"><span className="status-dot grey"/><span>iCloud calendars</span><span className="item-meta">Setup needed</span></div><div className="connection-line"><span className="status-dot grey"/><span>Assistant workflows</span><span className="item-meta">Awaiting writer</span></div></>}<button className="panel-link" onClick={() => navigate("sources")}>Explore the source network <Icon name="arrow" size={14}/></button></section></div>
      </>}
      {view === "calendar" && <><ViewHeading kicker="THE DAYS AHEAD" title="A little space for everything." subtitle={icloud.configured ? "Your shared household calendar. Apple events are read-only imports; edit their originals in Apple Calendar." : "Your household calendar. Hub events are shared here; Apple Calendar needs a verified connection."} action="Add event" onAction={() => add("calendar", { day: selectedDay })}/><section className="panel"><div className="calendar-toolbar"><div className="actions"><button className="icon-button" aria-label="Previous period" onClick={() => setSelectedDay(calendarMode === "month" ? shiftMonth(selectedDay, -1) : addDays(selectedDay, calendarMode === "day" ? -1 : -7))}><Icon name="back"/></button><h2>{formatDate(selectedDay, { month: "long", year: "numeric" })}</h2><button className="icon-button" aria-label="Next period" onClick={() => setSelectedDay(calendarMode === "month" ? shiftMonth(selectedDay, 1) : addDays(selectedDay, calendarMode === "day" ? 1 : 7))}><Icon name="arrow"/></button><button className="button small ghost" onClick={() => setSelectedDay(today)}>Today</button></div><div className="segmented">{["day", "week", "month"].map(mode => <button className={calendarMode === mode ? "active" : ""} key={mode} onClick={() => setCalendarMode(mode)}>{mode}</button>)}</div></div><div className="filter-row"><button className={`profile-filter ${!personFilter ? "active" : ""}`} onClick={() => setPersonFilter("")}>Everyone</button>{profiles.map(profile => <button className={`profile-filter ${personFilter === profile.data.name ? "active" : ""}`} key={profile.id} onClick={() => setPersonFilter(personFilter === profile.data.name ? "" : profile.data.name)}><span className="person-dot" style={{ background: profile.data.color }}/>{profile.data.name}</button>)}</div>{calendarSources.length > 0 && <div className="filter-row"><button className={`profile-filter ${!calendarFilter ? "active" : ""}`} onClick={() => setCalendarFilter("")}>All calendars</button><button className={`profile-filter ${calendarFilter === "__manual" ? "active" : ""}`} onClick={() => setCalendarFilter("__manual")}>Hub events</button>{calendarSources.map(calendar => <button className={`profile-filter ${calendarFilter === calendar.id ? "active" : ""}`} key={calendar.id} onClick={() => setCalendarFilter(calendar.id)}><span className="person-dot" style={{ background: calendar.color || "#78d3ef" }}/>{calendar.title}</button>)}</div>}{calendarMode === "day" ? <div className="day-agenda"><div className="section-label">{formatDate(selectedDay, { weekday: "long", day: "numeric", month: "long" })}</div>{eventsOn(selectedDay).map(renderEvent)}{!eventsOn(selectedDay).length && empty("No events loaded for this day.", "Add an event", () => add("calendar", { day: selectedDay }))}</div> : <div className={`calendar-grid ${calendarMode === "month" ? "month-grid" : ""}`}>{Array.from({ length: calendarMode === "week" ? 7 : 42 }, (_, i) => addDays(calendarMode === "week" ? weekStart(selectedDay) : weekStart(selectedDay.slice(0, 8) + "01"), i)).map(day => <div className={`calendar-day ${day === today ? "today" : ""} ${calendarMode === "month" && day.slice(0, 7) !== selectedDay.slice(0, 7) ? "outside" : ""}`} key={day}><button className="calendar-day-label" onClick={() => add("calendar", { day })}><span>{formatDate(day, { weekday: "short" })}</span><strong>{Number(day.slice(8))}</strong><Icon name="plus" size={12}/></button>{eventsOn(day).map(e => <button key={e.id} className="calendar-event" style={{ borderColor: e.data.color || personColour(e.data.person) }} onClick={() => setEditor({ kind: "calendar", item: e })}><span>{e.data.allDay ? "All day" : time(e.data.startAt)}</span><strong>{e.data.title}</strong>{e.data.origin === "icloud" && <small className="event-source-badge">Apple · read-only</small>}{e.data.status === "tentative" && <small>Tentative</small>}</button>)}</div>)}</div>}<div className="notice"><span className={`status-dot ${icloudSignal}`}/> {icloudLabel}. {icloud.lastSuccess ? "Apple events are read-only. Sync the iCloud source to bring in provider changes; imports cover the previous 30 days and next 180 days." : "Select the iCloud source in the source web to set it up and choose calendars."} Empty dates do not establish family availability.</div></section></>}
      {view === "lists" && <><ViewHeading kicker="LITTLE THINGS, TAKEN CARE OF" title="Pick it up. Tick it off." subtitle="One shared list, wherever you are. Completed items stay easy to restore." action="Add item" onAction={() => add("shopping", { listName })}/><section className="panel"><div className="list-header"><div className="filter-row">{lists.map(name => <button className={`profile-filter ${name === listName ? "active" : ""}`} onClick={() => setListName(name)} key={name}>{name}<span className="count-pill">{shopping.filter(r => r.data.listName === name && !r.data.done).length}</span></button>)}</div><button className="button ghost small" onClick={() => add("shopping", { listName: "" })}><Icon name="plus" size={14}/> New list</button></div><QuickAdd placeholder={`Add to ${listName}…`} label="Add shopping item" onAdd={async (title, key) => { await mutate("/api/items", "POST", { kind: "shopping", data: { title, listName, done: false } }, key); }}/><div className="section-label">TO PICK UP</div>{shopping.filter(r => r.data.listName === listName && !r.data.done).length ? listRows(shopping.filter(r => r.data.listName === listName && !r.data.done)) : empty("Everything’s picked up — or ready for your first item.")}<details className="completed-section" open={shopping.filter(r => r.data.listName === listName && r.data.done).length < 8}><summary className="section-label">COMPLETED · {shopping.filter(r => r.data.listName === listName && r.data.done).length} <span>tap a checkbox to restore</span></summary>{listRows(shopping.filter(r => r.data.listName === listName && r.data.done))}</details></section></>}
      {view === "reminders" && <><ViewHeading kicker="A LITTLE LESS TO HOLD IN YOUR HEAD" title="Family tasks." subtitle="A shared family checklist for chores, daily routines and things to remember. Tick a task when it’s done, or restore it from Completed." action="Add family task" onAction={() => add("reminder")}/><section className="panel"><div className="calendar-toolbar"><div className="filter-row"><button className={`profile-filter ${!taskFilter ? "active" : ""}`} onClick={() => setTaskFilter("")}>Everyone</button>{taskPeople.map(name => <button className={`profile-filter ${taskFilter === (name || "__unassigned") ? "active" : ""}`} key={name || "unassigned"} onClick={() => setTaskFilter(name || "__unassigned")}><span className="person-dot" style={{ background: personColour(name) }}/>{name || "Unassigned"}</button>)}</div><button className="button ghost small" onClick={() => add("profile")}><Icon name="plus" size={14}/> Add family member</button><div className="segmented"><button className={taskLayout === "board" ? "active" : ""} onClick={() => setTaskLayout("board")}>Family board</button><button className={taskLayout === "list" ? "active" : ""} onClick={() => setTaskLayout("list")}>List</button></div></div><div className="family-task-stats"><span><strong>{shownOpenTasks.length}</strong> open</span><span><strong>{shownOpenTasks.filter(r => r.data.dueAt && dateKey(r.data.dueAt) === today).length}</strong> due today</span><span><strong>{shownOpenTasks.filter(r => r.data.dueAt && Date.parse(r.data.dueAt) < now.getTime()).length}</strong> overdue</span></div><QuickAdd placeholder="Add a chore, routine or something to remember…" label="Add family task" onAdd={async (title, key) => { await mutate("/api/items", "POST", { kind: "reminder", data: { title, done: false, repeat: "none", ...(taskFilter && taskFilter !== "__unassigned" ? { assignedTo: taskFilter } : {}) } }, key); }}/>{taskLayout === "board" && !taskFilter ? <div className="family-task-board">{taskPeople.map(name => { const tasks = shownOpenTasks.filter(r => (r.data.assignedTo || "") === name); return <section className="family-task-column" key={name || "unassigned"}><div className="family-task-person"><span className="color-swatch" style={{ background: personColour(name) }}/><h2>{name || "Family / unassigned"}</h2><span className="count-pill">{tasks.length}</span></div>{tasks.length ? listRows(tasks) : <p className="subtle">All clear for now.</p>}<button className="panel-link" onClick={() => add("reminder", { assignedTo: name })}><Icon name="plus" size={14}/> Add task</button></section>; })}</div> : <><div className="section-label">OPEN · {shownOpenTasks.length}</div>{shownOpenTasks.length ? listRows(shownOpenTasks) : empty("No open family tasks. Enjoy the headspace.")}</>}<details className="completed-section"><summary className="section-label">COMPLETED · {shownTasks.filter(r => r.data.done).length} <span>tick again to restore</span></summary>{listRows(shownTasks.filter(r => r.data.done))}</details><p className="form-note" style={{ marginTop: 20 }}>Repeating routines advance to their next due date when ticked. These are shared website tasks; phone push notifications are not enabled.</p></section></>}
      {view === "recipes" && <><ViewHeading kicker="YOUR FAMILY COOKBOOK" title="Good things, kept together." subtitle="Your favourites, ready to cook. Choose portions, plan a meal and shop for exactly what you need." action="Add recipe" onAction={() => add("recipe")}/><div className="recipe-toolbar"><div className="search-field"><Icon name="search"/><input aria-label="Search recipes" placeholder="Find a recipe or tag…" value={search} onChange={e => setSearch(e.target.value)}/></div><button className="button ghost" onClick={() => setOnlineImport(true)}>Import recipe link</button><button className="button ghost" onClick={() => setScan(true)}><Icon name="camera"/> Scan recipe</button></div><div className="actions recipe-filters">{[["all", "All recipes"], ["family", "Our recipe cards"], ["online", "Our online recipes"]].map(([value, label]) => <button key={value} className={`button ${recipeFilter === value ? "primary" : "ghost"} small`} aria-pressed={recipeFilter === value} onClick={() => setRecipeFilter(value)}>{label}</button>)}</div>{recipes.length ? <div className="recipe-grid">{recipes.filter(r => recipeFilter === "all" || (recipeFilter === "online" ? !!r.data.sourceUrl : !r.data.sourceUrl)).filter(r => `${r.data.title} ${(r.data.tags || []).join(" ")}`.toLowerCase().includes(search.toLowerCase())).map(recipe => <button className="recipe-card panel" key={recipe.id} onClick={() => setCooking(recipe)}><div className="recipe-icon"><Icon name="book" size={30}/><span>{String(recipes.indexOf(recipe) + 1).padStart(2, "0")}</span></div><div className="recipe-tags">{(recipe.data.tags || []).slice(0, 3).map((tag: string) => <span className="tag" key={tag}>{tag}</span>)}</div><h2>{recipe.data.title}</h2><div className="recipe-meta"><span>{recipe.data.servings} {recipe.data.yieldUnit === "batches" ? "batch(es)" : "servings"}</span><span>{recipe.data.ingredients?.length || 0} ingredients</span>{recipe.data.cookMinutes && <span>{recipe.data.cookMinutes}m cook</span>}</div><span className="panel-link">Open recipe <Icon name="arrow" size={14}/></span></button>)}</div> : <section className="panel">{empty("Your cookbook starts with your first real recipe.", "Add a family favourite", () => add("recipe"))}<p className="form-note">No sample recipes are mixed into your collection.</p></section>}</>}
      {view === "meals" && <><ViewHeading kicker="MORE TIME AROUND THE TABLE" title="A week of good intentions." subtitle="Choose recipes or keep meals free-form. Your saved plans keep a recipe snapshot." action="Plan a meal" onAction={() => add("meal", { day: today, slot: "dinner" })}/><section className="panel"><div className="calendar-toolbar"><div className="actions"><button className="icon-button" aria-label="Previous week" onClick={() => setSelectedDay(addDays(selectedDay, -7))}><Icon name="back"/></button><h2>{formatDate(weekStart(selectedDay), { day: "numeric", month: "short" })} – {formatDate(addDays(weekStart(selectedDay), 6), { day: "numeric", month: "short" })}</h2><button className="icon-button" aria-label="Next week" onClick={() => setSelectedDay(addDays(selectedDay, 7))}><Icon name="arrow"/></button><button className="button ghost small" onClick={() => setSelectedDay(today)}>This week</button></div><span className="form-note">Attendance is editable. Rota not connected.</span></div><div className="meal-week">{Array.from({ length: 7 }, (_, i) => addDays(weekStart(selectedDay), i)).map(day => <div className={`meal-day ${day === today ? "today" : ""}`} key={day}><div className="meal-date"><span>{formatDate(day, { weekday: "long" })}</span><strong>{formatDate(day, { day: "numeric", month: "short" })}</strong></div>{["breakfast", "lunch", "dinner"].map(slot => { const planned = meals.filter(m => m.data.day === day && m.data.slot === slot); return <div className="meal-slot" key={slot}><div className="meal-slot-name">{slot}</div>{planned.map(meal => <div className="meal-choice" key={meal.id}><button onClick={() => setEditor({ kind: "meal", item: meal })}><strong>{meal.data.title || mealRecipe(meal)?.title || "Planned meal"}</strong><span>{meal.data.servings || mealRecipe(meal)?.servings || "—"} portions</span></button>{mealRecipe(meal) && <button className="panel-link" onClick={() => startIngredients(meal)}>Add ingredients to shopping list <Icon name="plus" size={12}/></button>}</div>)}{!planned.length && <button className="meal-add" aria-label={`Plan ${slot} for ${formatDate(day)}`} onClick={() => add("meal", { day, slot })}><Icon name="plus" size={14}/><span>Leave room for a plan</span></button>}</div>; })}</div>)}</div></section></>}
      {view === "sources" && <><ViewHeading kicker="FOLLOW THE THREADS" title="Your family’s constellation." subtitle="Every source has a place. Select a node to see its details and set up that source." action={hub.permissions?.admin && !wall ? "Add source" : undefined} onAction={() => add("source")}/><div className="sources-layout"><section className="panel network-panel"><div className="panel-header"><div><span className="panel-kicker">LIVE SOURCE MAP</span><h2 className="panel-title">Connected by the little things</h2></div><button className="button ghost small" onClick={() => void load()}><Icon name="refresh" size={14}/> Refresh saved status</button></div><SourceNetwork sources={sources} selected={sourceId} onSelect={setSourceId} now={now.getTime()}/><div className="legend"><span className="legend-item"><span className="status-dot green"/>Within 1 hour</span><span className="legend-item"><span className="status-dot yellow"/>1–24 hours</span><span className="legend-item"><span className="status-dot red"/>Over 1 day</span><span className="legend-item"><span className="status-dot grey"/>No successful check</span></div></section><section className="panel source-detail"><span className="panel-kicker">SOURCE INSPECTOR</span><SourceDetail source={(sources.length ? sources : UNCONFIGURED_SOURCES).find(s => s.id === sourceId)} now={now.getTime()} canConfigure={!!hub.permissions?.admin && !wall} busy={saveState === "saving"} onToggle={async (source, enabled) => { await mutate(`/api/sources/${encodeURIComponent(source.id)}/connection`, "POST", { enabled, version: source.version }); setToast(enabled ? "The hub will accept future updates from this source." : "Updates from this source are disabled in the hub."); }} onRefresh={() => load(true)} onAdd={source => add("source", { title: source.data.title, adapter: /icloud/i.test(source.id) ? "icloud" : "workflow" })}/><div className="notice">Source setup lives here, on the selected node. Receiving updates does not change a workflow’s schedule or paused state, and it does not refresh its data.</div></section></div></>}
      {view === "settings" && <><ViewHeading kicker="MAKE ROOM FOR YOUR FAMILY" title="Your household, your way." subtitle="Profiles and colours are shared settings. Device display choices stay on this screen." action="Add person" onAction={() => add("profile")}/><div className="settings-grid"><section className="panel"><div className="panel-header"><h2 className="panel-title">Family profiles</h2><Icon name="orbit"/></div>{profiles.map(profile => <button className="profile-row" key={profile.id} onClick={() => setEditor({ kind: "profile", item: profile })}><span className="color-swatch" style={{ background: profile.data.color }}/><strong>{profile.data.name}</strong><Icon name="edit" size={16}/></button>)}{!profiles.length && empty("Give everyone a name and a colour.", "Add a person", () => add("profile"))}</section><section className="panel"><h2 className="panel-title">Private by design</h2><p className="subtle">Private household access is managed separately from profiles. Each adult needs an explicit Sites visitor grant and a matching household invitation. Cross-account use is verified only after both adults sign in.</p><p className="subtle">Wall display is a layout, not a limited device session. Keep the tablet in a trusted place while it uses your owner account.</p><div className="actions"><button className="button ghost" onClick={toggleWall}><Icon name="display"/>{wall ? "Exit wall display" : "Enter wall display"}</button><a className="button ghost" href="/api/export"><Icon name="download"/> Export household JSON</a></div></section><section className="panel"><h2 className="panel-title">Dates &amp; connections</h2><p className="subtle">Household timezone: Europe/London. Work availability comes from verified calendar records, never a repeating rota assumption.</p><button className="panel-link" onClick={() => navigate("sources")}>Inspect connected sources <Icon name="arrow" size={14}/></button></section>{!wall && hub.permissions?.admin && <section className="panel"><h2 className="panel-title">Ryan’s admin space</h2><p className="subtle">Business and assistant results are kept behind a separate server permission and are never loaded by the family dashboard.</p><a className="button ghost" href="/admin"><Icon name="lock"/> Open protected admin</a></section>}</div></>}
      </>}
      <footer className="app-footer"><span>BIRD FAMILY HUB</span><span>ONE HOUSEHOLD · EUROPE/LONDON</span><span>{wall ? "WALL DISPLAY" : "YOUR LITTLE WORLD"}</span></footer>
    </main>
    {toast && <div className="toast" role="status">{toast}{undoRoutine && <button className="button ghost small" style={{ marginLeft: 12 }} onClick={async () => { try { await mutate(`/api/items/${encodeURIComponent(undoRoutine.item.id)}`, "PATCH", { version: undoRoutine.item.version, data: undoRoutine.data }); setUndoRoutine(null); setToast("Routine completion undone."); } catch {} }}>Undo</button>}</div>}
    {editor && <ItemEditor key={`${editor.kind}-${editor.item?.id || "new"}-${editor.initial?.title || ""}`} editor={editor} profiles={profiles} recipes={recipes} lists={lists} busy={saveState === "saving"} onClose={() => setEditor(null)} onSave={async (data, key) => { const kind = editor.kind; if (kind === "source" && !editor.item) { const existing = sources.find(source => source.data.sourceId === data.sourceId || (data.adapter === "icloud" && (source.data.adapter === "icloud" || source.data.sourceId === "icloud"))); if (existing) { if (data.adapter === "icloud") { setSourceId(existing.id); navigate("sources"); setEditor(null); setToast("Your existing iCloud source is selected. Choose additional calendars within it."); return; } throw new Error("A source with that identifier already exists. Select its node to configure it."); } } if (editor.item) await mutate(`/api/items/${encodeURIComponent(editor.item.id)}`, "PATCH", { version: editor.item.version, data }); else { const result = await mutate("/api/items", "POST", { kind, data }, key); if (kind === "source") { setSourceId(result.record.id); navigate("sources"); } } if (kind === "shopping") setListName(data.listName); setEditor(null); setToast(`${KIND_LABEL[kind] || "Item"} saved to your household.`); }} onDelete={editor.item ? () => void remove(editor.item!) : undefined}/>}
    {cooking && <Modal title={cooking.data.title} onClose={() => setCooking(null)} wide><RecipeDetail key={cooking.id} recipe={cooking.data} onShop={servings => { startIngredients(cooking, servings); setCooking(null); }} onPlan={servings => { add("meal", { recipeId: cooking.id, servings, day: today, slot: "dinner" }); setCooking(null); }} onEdit={() => { setEditor({ kind: "recipe", item: cooking }); setCooking(null); }}/></Modal>}
    {onlineImport && <OnlineRecipeImport onClose={() => setOnlineImport(false)} onDraft={draft => { setOnlineImport(false); setEditor({ kind: "recipe", initial: draft }); }}/>}
    {scan && <ScanRecipe onClose={() => setScan(false)} onExtract={draft => { setScan(false); setEditor({ kind: "recipe", initial: draft }); }}/> }
    {ingredientMeal && <Modal title="Check the cupboard first" onClose={() => setIngredientMeal(null)}><p className="subtle">Uncheck anything you already have. Quantities scale from the saved recipe to {importServings} {mealRecipe(ingredientMeal)?.yieldUnit === "batches" ? "batches" : "selected portions"}.</p><div className="field-row"><label className="field">{mealRecipe(ingredientMeal)?.yieldUnit === "batches" ? "Batches" : "Portions"}<input type="number" min="1" max="100" value={importServings} onChange={e => setImportServings(Number(e.target.value))}/></label><label className="field">Add to list<select value={importList} onChange={e => setImportList(e.target.value)}>{lists.map(name => <option key={name}>{name}</option>)}</select></label></div><div className="task-list">{(mealRecipe(ingredientMeal)?.ingredients || []).map((ingredient: any, index: number) => { const original = mealRecipe(ingredientMeal); const scaled = ingredient.amount !== undefined ? ingredient.amount * importServings / original.servings : undefined; return <label className="check-row" key={index}><input type="checkbox" checked={!excluded.includes(ingredient.name)} onChange={e => setExcluded(old => e.target.checked ? old.filter(n => n !== ingredient.name) : [...old, ingredient.name])}/><span className="item-copy"><strong>{ingredient.name}</strong><span className="item-meta">{scaled !== undefined ? `${Number(scaled.toFixed(3))} ${ingredient.unit || ""}` : "Quantity as written · review before buying"}</span></span></label>; })}</div><p className="form-note">Compatible units are combined by the server. Grams and millilitres stay separate. Repeated submission of this import will not duplicate items.</p><div className="modal-footer"><button className="button ghost" onClick={() => setIngredientMeal(null)}>Cancel</button><button className="button primary" disabled={saveState === "saving" || importServings < 1 || importServings > 100} onClick={() => void ingredientImport()}>{saveState === "saving" ? "Adding…" : "Add selected ingredients"}</button></div></Modal>}
  </div>;
}

function ViewHeading({ kicker, title, subtitle, action, onAction }: { kicker: string; title: string; subtitle: string; action?: string; onAction?: () => void }) { return <div className="view-heading"><div><p className="eyebrow">{kicker}</p><h1>{title}</h1><p className="subtle">{subtitle}</p></div>{action && <button className="button primary" onClick={onAction}><Icon name="plus"/>{action}</button>}</div>; }
function QuickAdd({ placeholder, label, onAdd }: { placeholder: string; label: string; onAdd: (text: string, key: string) => Promise<void> }) { const [value, setValue] = useState(""); const [busy, setBusy] = useState(false); const action = useRef({ value: "", key: "" }); const submit = async (event: React.FormEvent) => { event.preventDefault(); if (!value.trim() || busy) return; setBusy(true); try { if (action.current.value !== value.trim()) action.current = { value: value.trim(), key: crypto.randomUUID() }; await onAdd(value.trim(), action.current.key); action.current = { value: "", key: "" }; setValue(""); } catch {} finally { setBusy(false); } }; return <form className="inline-form" onSubmit={submit}><input aria-label={label} placeholder={placeholder} value={value} maxLength={300} onChange={e => setValue(e.target.value)} required/><button className="button primary" disabled={busy || !value.trim()} type="submit"><Icon name="plus"/>{busy ? "Saving…" : "Add"}</button></form>; }
function Modal({ title, onClose, children, wide = false }: { title: string; onClose: () => void; children: React.ReactNode; wide?: boolean }) { const ref = useRef<HTMLDivElement>(null); const closeRef = useRef(onClose); closeRef.current = onClose; useEffect(() => { const original = document.activeElement as HTMLElement | null; const oldOverflow = document.body.style.overflow; document.body.style.overflow = "hidden"; ref.current?.querySelector<HTMLElement>("input,select,textarea,button,a[href]")?.focus(); const handler = (event: KeyboardEvent) => { if (event.key === "Escape") closeRef.current(); if (event.key === "Tab") { const buttons = Array.from(ref.current?.querySelectorAll<HTMLElement>('button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled]),a[href]') || []); const first = buttons[0], last = buttons[buttons.length - 1]; if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last?.focus(); } else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first?.focus(); } } }; document.addEventListener("keydown", handler); return () => { document.body.style.overflow = oldOverflow; document.removeEventListener("keydown", handler); original?.focus(); }; }, []); return <div className="modal-backdrop" onMouseDown={e => { if (e.target === e.currentTarget) onClose(); }}><div className={`modal ${wide ? "wide" : ""}`} role="dialog" aria-modal="true" aria-label={title} ref={ref}><div className="modal-header"><h2>{title}</h2><button className="close-button icon-button" aria-label="Close dialog" onClick={onClose}><Icon name="close"/></button></div><div className="modal-body">{children}</div></div></div>; }

function OnlineRecipeImport({onClose,onDraft}:{onClose:()=>void;onDraft:(draft:any)=>void}) {
 const [url,setUrl]=useState("");const [busy,setBusy]=useState(false);const [error,setError]=useState("");
 return <Modal title="Save an online recipe" onClose={onClose}><p className="subtle">Paste a BBC Good Food, HelloFresh or Gousto recipe link. Review the ingredients and method, then save it in Our online recipes.</p><form onSubmit={async e=>{e.preventDefault();setBusy(true);setError("");try{const res=await fetch('/api/recipes/import-link',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({url})});const result:any=await res.json();if(!res.ok)throw new Error(result.error?.message||'Could not read the recipe.');onDraft(result.draft);}catch(e:any){setError(e.message);}finally{setBusy(false);}}}><label className="field">Recipe link<input required type="url" value={url} onChange={e=>setUrl(e.target.value)} placeholder="https://www.bbcgoodfood.com/recipes/…"/></label>{error&&<div className="notice" role="alert">{error}</div>}<p className="form-note">Only the recipe text is saved. Page images and adverts are left behind. Some websites block imports; you can always add the recipe manually and keep its source link.</p><div className="modal-footer"><button type="button" className="button ghost" onClick={onClose}>Cancel</button><button className="button primary" disabled={busy}>{busy?'Reading recipe…':'Read recipe'}</button></div></form></Modal>;
}

function ItemEditor({ editor, profiles, recipes, lists, busy, onClose, onSave, onDelete }: { editor: NonNullable<Editor>; profiles: Item[]; recipes: Item[]; lists: string[]; busy: boolean; onClose: () => void; onSave: (data: any, key?: string) => Promise<void>; onDelete?: () => void }) {
  const { kind, item } = editor; const data = { ...(editor.initial || {}), ...(item?.data || {}) };
  const defaultDay = data.day || dateKey();
  const [allDay, setAllDay] = useState(!!data.allDay);
  const [recipeId, setRecipeId] = useState(data.recipeId || "");
  const [sourceAdapter, setSourceAdapter] = useState(data.adapter || "workflow");
  const [formError, setFormError] = useState("");
  const [deleting, setDeleting] = useState(false);
  const requestKey = useRef(crypto.randomUUID());
  const field = (name: string, label: string, options: { type?: string; value?: any; required?: boolean; placeholder?: string; min?: string; max?: string; step?: string } = {}) => <label className="field">{label}<input key={`${name}-${options.type || "text"}`} name={name} type={options.type || "text"} defaultValue={options.value ?? data[name] ?? ""} required={options.required} disabled={data.origin === "icloud"} placeholder={options.placeholder} min={options.min} max={options.max} step={options.step} maxLength={options.type === "url" ? 2000 : 1000}/></label>;
  const textarea = (name: string, label: string, value = data[name] || "", rows = 4, required = false) => <label className="field">{label}<textarea name={name} defaultValue={value} rows={rows} required={required} disabled={data.origin === "icloud"} maxLength={30000}/></label>;
  const person = (name: string, label: string) => <label className="field">{label}<select name={name} defaultValue={data[name] || ""} disabled={data.origin === "icloud"}><option value="">Everyone / unassigned</option>{profiles.map(p => <option key={p.id} value={p.data.name}>{p.data.name}</option>)}</select></label>;
  const submit = async (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault(); if (busy) return; setFormError(""); const fd = new FormData(event.currentTarget); const str = (name: string) => String(fd.get(name) || "").trim(); const num = (name: string) => Number(str(name));
    try { let payload: any;
      if (kind === "shopping") payload = { title: str("title"), listName: str("listName") || "Groceries", quantity: str("quantity"), category: str("category"), done: data.done || false };
      else if (kind === "reminder") payload = { title: str("title"), dueAt: str("dueAt") ? londonISO(str("dueAt")) : null, assignedTo: str("assignedTo"), repeat: str("repeat") || "none", done: data.done || false, notes: str("notes") };
      else if (kind === "calendar") { const startAt = londonISO(str("startAt")), endAt = londonISO(str("endAt")); if (Date.parse(endAt) <= Date.parse(startAt)) throw new Error("The end must be after the start."); payload = { title: str("title"), startAt, endAt, allDay, person: str("person"), location: str("location"), notes: str("notes"), status: str("status"), origin: data.origin || "manual" }; }
      else if (kind === "recipe") { const ingredients = parseIngredients(str("ingredients")); if (!ingredients.length) throw new Error("Add at least one ingredient."); payload = { title: str("title"), yieldUnit: data.yieldUnit || "people", servings: num("servings"), ingredients, instructions: str("instructions"), notes: str("notes"), tags: str("tags").split(",").map(s => s.trim()).filter(Boolean), prepMinutes: str("prepMinutes") ? num("prepMinutes") : null, cookMinutes: str("cookMinutes") ? num("cookMinutes") : null, sourceUrl: str("sourceUrl") || null }; }
      else if (kind === "meal") { const recipe = recipes.find(r => r.id === recipeId); const retained = item && item.data.recipeId === recipeId ? item.data.recipeSnapshot : undefined; const snapshot = retained || recipe?.data; if (!recipeId && !str("title")) throw new Error("Choose a recipe or write a meal name."); payload = { day: str("day"), slot: str("slot"), servings: num("servings"), ...(recipeId ? { recipeId, recipeSnapshot: snapshot, title: snapshot?.title || str("title") } : { title: str("title"), recipeId: null, recipeSnapshot: null }) }; }
      else if (kind === "profile") payload = { name: str("name"), color: str("color") };
      else if (kind === "source") payload = { title: str("title") || (sourceAdapter === "icloud" ? "iCloud calendars" : ""), sourceId: sourceAdapter === "icloud" ? "icloud" : str("sourceId"), adapter: sourceAdapter, runStatus: "awaiting_access", connectionEnabled: false };
      await onSave(payload, requestKey.current);
    } catch (error: any) { setFormError(error.message || "Could not save this item."); }
  };
  return <Modal title={data.origin === "icloud" ? "Apple event · read-only" : `${item ? "Edit" : "Add"} ${KIND_LABEL[kind] || kind}`} onClose={onClose} wide={kind === "recipe"}>
    <form onSubmit={submit}>
      {kind === "shopping" && <>{field("title", "Item", { required: true, placeholder: "What do we need?" })}<div className="field-row">{field("quantity", "Quantity", { placeholder: "e.g. 2 cartons" })}{field("category", "Category", { placeholder: "e.g. Fruit & veg" })}</div><label className="field">List<input name="listName" list="household-lists" defaultValue={data.listName ?? "Groceries"} maxLength={100} required/><datalist id="household-lists">{lists.map(name => <option value={name} key={name}/>)}</datalist></label></>}
      {kind === "reminder" && <>{field("title", "Remember to…", { required: true })}<div className="field-row">{field("dueAt", "Due (London time)", { type: "datetime-local", value: localInput(data.dueAt) })}{person("assignedTo", "Who’s on it?")}</div><label className="field">Repeat<select name="repeat" defaultValue={data.repeat || "none"}><option value="none">Does not repeat</option><option value="daily">Every day</option><option value="weekly">Every week</option><option value="monthly">Every month</option></select></label>{textarea("notes", "Notes", undefined, 3)}<p className="form-note">Recurring tasks advance their due date when completed. No phone push notification is implied.</p></>}
      {kind === "calendar" && <>{data.origin === "icloud" && <div className="notice warning">This is a read-only iCloud import. Edit the original in Apple Calendar, then sync the iCloud source to bring its updates here.</div>}{field("title", "Event title", { required: true })}<label className="check-row"><input type="checkbox" checked={allDay} disabled={data.origin === "icloud"} onChange={e => setAllDay(e.target.checked)}/>All day</label><div className="field-row">{field("startAt", allDay ? "Starts on" : "Starts (London time)", { type: allDay ? "date" : "datetime-local", value: allDay ? (data.startAt ? dateKey(data.startAt) : defaultDay) : (localInput(data.startAt) || `${defaultDay}T09:00`), required: true })}{field("endAt", allDay ? "Ends on (exclusive)" : "Ends (London time)", { type: allDay ? "date" : "datetime-local", value: allDay ? (data.endAt ? dateKey(data.endAt) : addDays(defaultDay, 1)) : (localInput(data.endAt) || `${defaultDay}T10:00`), required: true })}</div><div className="field-row">{person("person", "Person")}<label className="field">Status<select name="status" defaultValue={data.status || "confirmed"} disabled={data.origin === "icloud"}><option value="confirmed">Confirmed</option><option value="tentative">Tentative</option></select></label></div>{field("location", "Location")}{textarea("notes", "Notes", undefined, 3)}<p className="form-note">{data.origin === "icloud" ? "Apple Calendar remains the source of truth for this event." : "Saved to Bird Family Hub. This does not write to Apple Calendar."}</p></>}
      {kind === "recipe" && <><div className="notice">Review every quantity and instruction before saving. Scanned images are not retained with recipes.</div>{field("title", "Recipe title", { required: true })}<div className="field-row">{field("servings", "Servings", { type: "number", min: "1", max: "100", value: data.servings || 4, required: true })}{field("prepMinutes", "Preparation (minutes)", { type: "number", min: "0", max: "10000" })}{field("cookMinutes", "Cooking (minutes)", { type: "number", min: "0", max: "10000" })}</div>{textarea("ingredients", "Ingredients · one per line", ingredientsText(data.ingredients), 7, true)}<p className="form-note">Use “200 g rice” or “2 eggs”. Unclear or fractional quantities remain as written for your review; they are never guessed or silently converted.</p>{textarea("instructions", "Method", data.instructions || "", 7, true)}{field("tags", "Categories / tags (comma separated)", { value: (data.tags || []).join(", "), placeholder: "Quick dinner, vegetarian…" })}{field("sourceUrl", "Original source link (optional)", { type: "url" })}{textarea("notes", "Notes / uncertain text", undefined, 3)}</>}
      {kind === "meal" && <><div className="field-row">{field("day", "Day", { type: "date", value: defaultDay, required: true })}<label className="field">Meal<select name="slot" defaultValue={data.slot || "dinner"}><option value="breakfast">Breakfast</option><option value="lunch">Lunch</option><option value="dinner">Dinner</option></select></label></div><label className="field">Choose a recipe<select value={recipeId} onChange={e => setRecipeId(e.target.value)}><option value="">A simple free-text meal</option>{recipes.map(r => <option key={r.id} value={r.id}>{r.data.title}</option>)}</select></label>{!recipeId && field("title", "What’s on the menu?", { required: true })}{field("servings", "Planned portions", { type: "number", min: "1", max: "100", value: data.servings || recipes.find(r => r.id === recipeId)?.data.servings || 4, required: true })}<p className="form-note">Portions are your editable assumption. Family attendance and work rota have not been connected. A saved recipe snapshot preserves this meal if the original changes.</p></>}
      {kind === "profile" && <>{field("name", "Name", { required: true })}{field("color", "Family colour", { type: "color", value: data.color || COLOURS[profiles.length % COLOURS.length] })}<p className="form-note">A profile is a calendar label. It does not create an account or grant Site access.</p></>}
      {kind === "source" && <>{field("title", "Source name", { required: sourceAdapter !== "icloud", placeholder: "Give this source a recognisable name" })}<label className="field">Source type<select name="adapter" value={sourceAdapter} onChange={event => setSourceAdapter(event.target.value)}><option value="workflow">Existing assistant workflow</option><option value="icloud">iCloud calendar</option><option value="manual">Manual / other source</option></select></label>{sourceAdapter === "icloud" ? <p className="notice">One private Apple account connects through the existing iCloud source. Select multiple calendars inside that source; adding this type will open the existing node when present.</p> : field("sourceId", "Stable workflow or source identifier", { required: true, placeholder: "Use the existing workflow’s exact identifier" })}<p className="form-note">This adds a node to your source web. It does not create a schedule, request credentials, or claim the source is connected. Select the node afterwards to see its setup path.</p></>}
      {formError && <p className="error-text" role="alert">{formError}</p>}
      <div className="modal-footer">{onDelete && <button className="button danger ghost" type="button" disabled={busy || data.origin === "icloud"} onClick={() => deleting ? onDelete() : setDeleting(true)}>{deleting ? "Confirm remove" : "Remove"}</button>}<button className="button ghost" type="button" onClick={onClose}>Cancel</button><button className="button primary" type="submit" disabled={busy || data.origin === "icloud"}>{busy ? "Saving…" : `Save ${KIND_LABEL[kind] || "item"}`}</button></div>
    </form>
  </Modal>;
}

function SourceNetwork({ sources, selected, onSelect, now }: { sources: Item[]; selected: string; onSelect: (id: string) => void; now: number }) {
  const actual = sources.length ? sources : UNCONFIGURED_SOURCES;
  const nodes = actual.map((s, i) => { const a = (i / actual.length) * Math.PI * 2 - Math.PI / 2; const radius = i % 2 ? 176 : 145; return { source: s, x: 300 + Math.cos(a) * radius, y: 225 + Math.sin(a) * radius, colour: freshness(s, now) }; });
  const colorMap: Record<string, string> = { green: "#69d7a7", yellow: "#e0bd6a", red: "#ed8b91", grey: "#637b8e" };
  return <div className="source-network"><svg viewBox="0 0 600 450" role="img" aria-label="Spiderweb of household information sources"><defs><radialGradient id="core-glow"><stop offset="0" stopColor="#8fe7ff" stopOpacity=".45"/><stop offset="1" stopColor="#46d3ff" stopOpacity="0"/></radialGradient><filter id="node-glow"><feGaussianBlur stdDeviation="3"/></filter></defs><circle cx="300" cy="225" r="155" fill="url(#core-glow)"/><circle cx="300" cy="225" r="185" fill="none" stroke="#8eb4b4" strokeWidth=".5" strokeDasharray="3 10"/><circle cx="300" cy="225" r="125" fill="none" stroke="#8eb4b4" strokeWidth=".5"/>{nodes.map((n, i) => <g key={`web-${n.source.id}`}><path d={`M300 225 Q${(n.x + 300) / 2 + 15} ${(n.y + 225) / 2 - 20} ${n.x} ${n.y}`} fill="none" stroke={colorMap[n.colour]} strokeWidth={selected === n.source.id ? "1.5" : ".8"} opacity=".55"/>{nodes.slice(i + 1, i + 4).map(next => <path key={next.source.id} d={`M${n.x} ${n.y} L${next.x} ${next.y}`} stroke={colorMap[n.colour]} strokeWidth=".45" opacity=".2"/>)}</g>)}<circle cx="300" cy="225" r="48" fill="#061522" stroke="#69d6ef" strokeOpacity=".6"/><circle cx="300" cy="225" r="38" fill="none" stroke="#69d6ef" strokeOpacity=".3"/><text x="300" y="222" textAnchor="middle" fill="#d0f6ff" fontSize="18" letterSpacing="4">BIRD</text><text x="300" y="239" textAnchor="middle" fill="#6eabba" fontSize="7" letterSpacing="2">FAMILY HUB</text>{nodes.map(n => <g key={n.source.id} className={`network-node ${selected === n.source.id ? "selected" : ""}`} role="button" tabIndex={0} aria-label={`${n.source.data.title}: ${age(n.source.data.lastSuccess, now)}, ${n.source.data.runStatus}`} onClick={() => onSelect(n.source.id)} onKeyDown={e => { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); onSelect(n.source.id); } }}><circle cx={n.x} cy={n.y} r="24" fill={colorMap[n.colour]} opacity=".08"/><circle cx={n.x} cy={n.y} r="7" fill={colorMap[n.colour]} filter="url(#node-glow)" opacity=".6"/><circle cx={n.x} cy={n.y} r="5" fill={colorMap[n.colour]}/><circle cx={n.x} cy={n.y} r="12" stroke={colorMap[n.colour]} fill="transparent" strokeOpacity=".35"/><text className="network-label" x={n.x} y={n.y + (n.y > 225 ? 30 : -23)} textAnchor="middle" fill="#29474d" fontSize="10">{n.source.data.title}</text><text className="network-detail" x={n.x} y={n.y + (n.y > 225 ? 44 : -9)} textAnchor="middle" fill="#617c80" fontSize="8">{age(n.source.data.lastSuccess, now)}</text></g>)}</svg>{!sources.length && <p className="form-note">Source placeholders show connection requirements. No live results or successful checks are being implied.</p>}<div className="sr-only">{actual.map(source => <button key={source.id} onClick={() => onSelect(source.id)}>{source.data.title}: {source.data.runStatus}</button>)}</div></div>;
}
function SourceDetail({ source, now, canConfigure, busy, onToggle, onAdd, onRefresh }: { source?: Item; now: number; canConfigure: boolean; busy: boolean; onRefresh: () => Promise<boolean>; onToggle: (source: Item, enabled: boolean) => Promise<void>; onAdd: (source: Item) => void }) {
  const [setupError, setSetupError] = useState("");
  useEffect(() => setSetupError(""), [source?.id]);
  if (!source) return <><h2 className="panel-title">Every signal has a story.</h2><p className="subtle">Select a source in the web to see its latest result and set up that source here.</p></>;
  const status: Record<string, string> = { ready: "Latest saved result available", stale: "Last result retained", error: "Source check failed", awaiting_access: "Needs access / configuration", paused: "Paused" };
  const adapter = source.data.adapter || (/icloud/i.test(`${source.id} ${source.data.sourceId || ""} ${source.data.title || ""}`) ? "icloud" : "manual");
  const registered = source.version > 0;
  const statusOnly = /email[ _-]*organi[sz]|transport[ _-]*(reminder|status)?/i.test(`${source.data.sourceId || ""} ${source.data.title || ""}`);
  const workflow = adapter === "workflow";
  const enabled = !!source.data.connectionEnabled;
  const paused = source.data.schedulePaused === true || source.data.runStatus === "paused";
  const toggle = async (value: boolean) => { setSetupError(""); try { await onToggle(source, value); } catch (error: any) { setSetupError(error.message || "Source setup could not be saved."); } };
  return <><h2 className="panel-title">{source.data.title}</h2><span className="source-adapter-pill">{workflow ? "Assistant workflow" : adapter === "icloud" ? "iCloud calendar" : "Saved / manual source"}</span><div className="connection-line"><span className={`status-dot ${freshness(source, now)}`}/><strong>{status[source.data.runStatus] || source.data.runStatus}</strong></div>
    <div className="source-setup"><h3 className="source-setup-title">{statusOnly ? "Job completion status" : "Set up this source"}</h3>
      {statusOnly ? <><div className="setup-status"><span className={`status-dot ${source.data.runStatus === "error" ? "red" : source.data.lastSuccess ? freshness(source, now) : "grey"}`}/><span>{source.data.runStatus === "error" ? "The latest reported run needs attention." : source.data.runStatus === "stale" ? "The latest job report is partial or has outstanding work." : source.data.runStatus === "paused" ? "The existing job is paused; its last reported status is retained." : source.data.lastSuccess && source.data.runStatus === "ready" ? "The existing job reported a successful completion." : "No fully completed run has been verified by the hub yet."}</span></div><p className="subtle">{source.data.lastSuccess ? `Last successful check: ${formatDate(source.data.lastSuccess)} at ${time(source.data.lastSuccess)} London time.` : "This is a status signal for the existing job, not a manual data-entry source. A missing status does not mean the job failed or has no work to do."}</p><p className="form-note">The job can publish a simple success or failure after it actually finishes. Its existing execution location, schedule and destinations stay unchanged.</p></> : workflow && registered ? <>{canConfigure ? <label className="connection-toggle"><span><strong>Receive updates</strong><small>Let this workflow deliver its results to the hub.</small></span><input type="checkbox" role="switch" checked={enabled} disabled={busy} onChange={e => void toggle(e.target.checked)} aria-label={`Receive updates from ${source.data.title}`}/></label> : <p className="subtle">{enabled ? "This source is enabled to receive workflow results." : "Receiving is disabled for this source."} The household owner can change this setting.</p>}<div className={`setup-status ${enabled ? "enabled" : ""}`}><span className={`status-dot ${enabled ? "green" : "grey"}`}/><span>{paused ? "The existing workflow is paused. Its paused state is preserved." : enabled ? "Waiting for the next scheduled delivery. Enabling this does not run the workflow now." : "Enable receiving to accept future deliveries from this workflow."}</span></div>{source.data.scheduleLabel && <p className="subtle"><strong>Existing schedule:</strong> {source.data.scheduleLabel}</p>}<p className="form-note">{source.data.automationId && "This source refers to the existing workflow. Scheduled delivery is verified only after a run saves its result here. "}{source.data.nextRunAt ? `Next reported run: ${formatDate(source.data.nextRunAt)} at ${time(source.data.nextRunAt)} London time.` : paused ? "No next delivery while the workflow remains paused." : "Next scheduled run has not yet been reported to the hub."} The original workflow keeps its own schedule and must have a working delivery connection.</p>{source.data.connectionConfiguredAt && <p className="form-note">Receiving last changed {formatDate(source.data.connectionConfiguredAt)} at {time(source.data.connectionConfiguredAt)}. Source freshness still uses the successful check below.</p>}</>
      : adapter === "icloud" ? canConfigure ? <ICloudSetup onRefresh={onRefresh}/> : <><div className="setup-status"><span className={`status-dot ${freshness(source, now)}`}/><span>Private iCloud calendar source</span></div><p className="subtle">The household owner can connect an Apple account and choose calendars here. If you are using the owner account in wall display, exit wall display to open the private account form.</p><p className="form-note">Apple Calendar remains the source of truth. Imported events are read-only in the hub.</p></>
      : <><p className="subtle">{registered ? "This source stores explicitly delivered or imported results. It has no automatic provider connection to switch on here." : "This node is a setup placeholder. Add it as a source before linking an existing workflow or verified adapter."}</p>{canConfigure && !registered && <button className="button ghost source-add-button" onClick={() => onAdd(source)}><Icon name="plus" size={15}/> Add this source</button>}</>}
      {setupError && <p className="error-text" role="alert">{setupError}</p>}
    </div>
    <dl className="source-facts"><dt>Last successful check</dt><dd>{source.data.lastSuccess ? `${formatDate(source.data.lastSuccess)} at ${time(source.data.lastSuccess)} · ${age(source.data.lastSuccess, now)}` : "No successful check recorded"}</dd><dt>Last observation</dt><dd>{source.data.observedAt ? `${formatDate(source.data.observedAt)} at ${time(source.data.observedAt)}` : "Not yet observed"}</dd><dt>Source identifier</dt><dd>{source.data.sourceId || "Not configured"}</dd></dl>{source.data.detail && <p className="subtle">{source.data.detail}</p>}{safeLink(source.data.sourceLink) && <a className="panel-link" href={safeLink(source.data.sourceLink)} target="_blank" rel="noreferrer">Open original workflow <Icon name="arrow" size={14}/></a>}</>;
}

function BriefingCard({ kind, feed, now, today, onSource }: { kind: "news" | "travel" | "weekly"; feed?: HouseholdFeed; now: number; today: string; onSource: () => void }) {
  const [fullOpen, setFullOpen] = useState(false);
  const isNews = kind === "news";
  const isWeekly = kind === "weekly";
  const dailyDashboard = isWeekly && !!feed && /daily/i.test(feed.workflow);
  const summaryOnly = isWeekly && feed?.runStatus === "awaiting_access";
  const current = feed ? dateKey(feed.observedAt) === today : false;
  const status: Record<string, string> = { ready: "Saved result", stale: "Last known result", error: "Latest check failed", awaiting_access: "Waiting for access", paused: "Workflow paused" };
  const colour = feed ? freshness({ data: { lastSuccess: feed.lastSuccess } }, now) : "grey";
  const original = feed?.body || "";
  const summary = feed?.summary || (original.length > 600 ? original.slice(0, 600).replace(/\s+\S*$/, "") + "…" : original);
  return <><section className={`panel briefing-card ${kind}`}><div className="briefing-header"><span className="briefing-icon"><Icon name={isNews ? "book" : isWeekly ? "check" : "orbit"} size={22}/></span><div><span className="panel-kicker">{isNews ? "YOUR DAILY BRIEFING" : isWeekly ? (dailyDashboard ? "YOUR SHARED DAILY OVERVIEW" : "YOUR SHARED OVERVIEW") : "FAMILY TRAVEL RADAR"}</span><h2 className="panel-title">{isNews ? (current ? "Today’s news" : "Latest news briefing") : isWeekly ? "Ryan’s dashboard" : "Family holiday & travel watch"}</h2></div><button className="icon-button" aria-label={`Set up ${isNews ? "news" : isWeekly ? "weekly dashboard" : "travel"} source`} onClick={onSource}><Icon name="network"/></button></div>{feed ? <><div className="briefing-meta"><span className={`status-dot ${colour}`}/><span>{formatDate(feed.observedAt, { weekday: "short", day: "numeric", month: "short" })} · {time(feed.observedAt)} London</span><span className="briefing-status">{status[feed.runStatus] || feed.runStatus}</span></div><h3 className="briefing-title">{feed.title}</h3>{summary && <div className="briefing-summary"><ReportContent body={summary} originalUrl={feed.sourceLink}/></div>}{original && <button className="button ghost briefing-read-button" onClick={() => setFullOpen(true)}>{summaryOnly ? "Read verified summary" : `Read full ${isNews ? "briefing" : isWeekly ? "dashboard" : "update"}`} <Icon name="arrow" size={14}/></button>}<div className="briefing-footer"><span>Last successful check: {feed.lastSuccess ? age(feed.lastSuccess, now) : "Not recorded"}</span>{safeLink(feed.sourceLink) && <a className="panel-link report-source-link" href={safeLink(feed.sourceLink)} target="_blank" rel="noreferrer">View original in ChatGPT <Icon name="arrow" size={13}/></a>}</div>{!current && <p className="form-note">This is the latest saved update, dated {formatDate(feed.observedAt)}. It is not presented as today’s result.</p>}</> : <div className="feed-empty"><p>{isNews ? "No household news briefing has been delivered yet." : isWeekly ? "The existing dashboard has not been delivered to the shared feed yet. This does not mean there are no actions." : "No household travel update has been delivered yet."}</p><button className="panel-link" onClick={onSource}>Set up this source <Icon name="arrow" size={14}/></button></div>}</section>{fullOpen && feed && original && <Modal title={feed.title} wide onClose={() => setFullOpen(false)}><div className="report-modal"><div className="report-original-note"><p>{summaryOnly ? "Verified dashboard summary" : "Original ChatGPT report"} · {formatDate(feed.observedAt)} at {time(feed.observedAt)} London time. {summaryOnly ? "The actions below come from the existing report and its verified correction records. The complete original report copy has not been delivered to the hub yet; this summary does not replace it." : "The complete saved original text is shown below; presentation wrappers are adapted for reading. Source citations and unavailable interactive images open the original report."}</p>{safeLink(feed.sourceLink) && <a className="panel-link report-source-link" href={safeLink(feed.sourceLink)} target="_blank" rel="noreferrer">View original in ChatGPT <Icon name="arrow" size={14}/></a>}</div><ReportContent body={original} originalUrl={feed.sourceLink}/></div></Modal>}</>;
}

function ICloudSetup({ onRefresh }: { onRefresh: () => Promise<boolean> }) {
  const [status, setStatus] = useState<ICloudStatus | null>(null);
  const [username, setUsername] = useState("");
  const [selection, setSelection] = useState<string[]>([]);
  const [loading, setLoading] = useState(true);
  const [busyAction, setBusyAction] = useState("");
  const [message, setMessage] = useState("");
  const [requestError, setRequestError] = useState("");
  const [changingAccount, setChangingAccount] = useState(false);
  const [confirmDisconnect, setConfirmDisconnect] = useState(false);
  const [removeImported, setRemoveImported] = useState(false);
  const passwordInput = useRef<HTMLInputElement>(null);
  const controller = useRef<AbortController | null>(null);
  const mounted = useRef(false);
  const operationBusy = useRef(false);
  const refreshRef = useRef(onRefresh);
  refreshRef.current = onRefresh;
  const readStatus = async (signal?: AbortSignal) => {
    const response = await fetch("/api/icloud/status", { credentials: "same-origin", cache: "no-store", signal });
    const result: any = await response.json();
    if (!response.ok) throw new Error(result.error?.message || result.error || "The iCloud connection status could not be loaded.");
    if (mounted.current) { setStatus(result); setUsername(result.username || ""); setSelection(result.selectedCalendarIds || []); }
    return result as ICloudStatus;
  };
  useEffect(() => {
    mounted.current = true;
    const abort = new AbortController(); controller.current = abort;
    void readStatus(abort.signal).catch(error => { if (mounted.current && error.name !== "AbortError") setRequestError(error.message); }).finally(() => { if (mounted.current) setLoading(false); });
    const clearHiddenPassword = () => { if (document.visibilityState !== "visible" && passwordInput.current) passwordInput.current.value = ""; };
    document.addEventListener("visibilitychange", clearHiddenPassword);
    return () => { mounted.current = false; controller.current?.abort(); document.removeEventListener("visibilitychange", clearHiddenPassword); if (passwordInput.current) passwordInput.current.value = ""; };
  }, []);
  const perform = async (path: string, method: string, requestBody: string, action: string, success: string) => {
    if (operationBusy.current) return false;
    operationBusy.current = true; controller.current?.abort();
    const abort = new AbortController(); controller.current = abort;
    const timeout = setTimeout(() => abort.abort(), 45000);
    setBusyAction(action); setRequestError(""); setMessage("");
    try {
      const pending = fetch(path, { method, credentials: "same-origin", headers: { "Content-Type": "application/json" }, body: requestBody, cache: "no-store", signal: abort.signal });
      requestBody = "";
      const response = await pending;
      const result: any = await response.json();
      if (!response.ok) throw new Error(result.error?.message || result.error || "The iCloud action could not be completed.");
      await readStatus(abort.signal);
      await refreshRef.current();
      if (mounted.current) setMessage(success);
      return true;
    } catch (error: any) {
      if (mounted.current) setRequestError(error.name === "AbortError" ? "The request was interrupted or timed out. The last imported events are retained. Refresh saved status before retrying; the server may have completed the request." : error.message || "The iCloud action failed. No successful sync is being claimed.");
      return false;
    } finally {
      requestBody = ""; clearTimeout(timeout); operationBusy.current = false;
      if (passwordInput.current) passwordInput.current.value = "";
      if (mounted.current) setBusyAction("");
    }
  };
  const connect = (event: React.FormEvent) => {
    event.preventDefault(); if (operationBusy.current || !passwordInput.current?.value) return;
    let requestBody = JSON.stringify({ username: username.trim(), password: passwordInput.current.value });
    passwordInput.current.value = "";
    void perform("/api/icloud/connect", "POST", requestBody, "connect", "Apple account verified. Choose the calendars to import below.").then(ok => { if (ok && mounted.current) setChangingAccount(false); });
    requestBody = "";
  };
  const saveAndSync = async () => {
    if (!selection.length || operationBusy.current) return;
    const saved = await perform("/api/icloud/calendars", "POST", JSON.stringify({ calendarIds: selection }), "selection", "Calendar selection saved.");
    if (saved && mounted.current) await perform("/api/icloud/sync", "POST", "{}", "sync", "Selected calendars synced from Apple. Read-only events are now shared in the hub.");
  };
  const disconnect = async () => {
    const ok = await perform("/api/icloud/config", "DELETE", JSON.stringify({ removeImported }), "disconnect", removeImported ? "iCloud disconnected. Its imported events were removed; your Hub events were kept." : "iCloud disconnected. Saved credentials were removed and the last imported events were kept.");
    if (ok && mounted.current) { setConfirmDisconnect(false); setChangingAccount(false); setRemoveImported(false); }
  };
  if (loading) return <p className="subtle" role="status">Checking this Site’s private iCloud connection…</p>;
  const busy = !!busyAction;
  const configured = !!status?.configured;
  return <div className="icloud-setup">
    {configured && <><div className="setup-status"><span className={`status-dot ${status?.lastSuccess ? freshness({ data: { lastSuccess: status.lastSuccess } }, Date.now()) : "grey"}`}/><span>{status?.status === "error" ? "The latest iCloud check needs attention." : status?.lastSuccess ? "A verified calendar sync is available." : "Apple account verified. Calendar sync is pending."}</span></div><p className="subtle">Apple account: <strong>{status?.username}</strong></p></>}
    {(!configured || changingAccount) && <form className="icloud-connect-form" onSubmit={connect} autoComplete="off"><p className="subtle">Connect one private Apple account for the household with an <strong>app-specific password</strong>. Use an app-specific password, never your main Apple password.</p><label className="field">Apple ID email<input type="email" autoComplete="username" autoCapitalize="none" spellCheck={false} value={username} onChange={event => setUsername(event.target.value)} maxLength={320} required disabled={busy}/></label><label className="field">Apple app-specific password<input ref={passwordInput} type="password" autoComplete="new-password" autoCapitalize="none" spellCheck={false} placeholder="xxxx-xxxx-xxxx-xxxx" required disabled={busy} maxLength={100}/></label><p className="form-note">The password is sent privately to this Site and stored encrypted on the server for read-only calendar access. The form clears it as soon as you submit. The hub does not save it in browser storage. Do not paste it into this chat.</p><a className="panel-link" href="https://support.apple.com/en-us/102654" target="_blank" rel="noreferrer">Apple: create an app-specific password <Icon name="arrow" size={13}/></a><p className="form-note">Apple two-factor authentication is required. Create the app password in Apple Account → Sign-In and Security → App-Specific Passwords.</p><div className="actions"><button className="button primary" type="submit" disabled={busy}>{busyAction === "connect" ? "Testing Apple connection…" : "Test & connect"}</button>{configured && <button className="button ghost" type="button" disabled={busy} onClick={() => { if (passwordInput.current) passwordInput.current.value = ""; setChangingAccount(false); }}>Cancel</button>}</div></form>}
    {configured && !changingAccount && <><div className="icloud-calendar-list"><h3>Choose up to eight calendars</h3><p className="form-note">Only the calendars you select will be shared into the household. Deselecting a calendar removes its imported events from the hub; manually added Hub events are kept. Apple Calendar remains the source of truth.</p>{status?.calendars?.length ? status.calendars.map(calendar => <label className="icloud-calendar-choice check-row" key={calendar.id}><input type="checkbox" checked={selection.includes(calendar.id)} disabled={busy || (!selection.includes(calendar.id) && selection.length >= 8)} onChange={event => setSelection(current => event.target.checked ? [...current, calendar.id] : current.filter(id => id !== calendar.id))}/><span className="person-dot" style={{ background: calendar.color || "#78d3ef" }}/><span>{calendar.displayName}</span></label>) : <p className="subtle">No calendars were returned by the account check.</p>}</div><div className="actions"><button className="button primary" disabled={busy || !selection.length} onClick={() => void saveAndSync()}><Icon name="refresh" size={15}/>{busyAction === "selection" ? "Saving selection…" : busyAction === "sync" ? "Syncing Apple Calendar…" : "Save calendars & sync now"}</button><button className="button ghost small" disabled={busy} onClick={() => setChangingAccount(true)}>Change Apple account</button></div><p className="form-note" style={{ marginTop: 14 }}>Imports cover the previous 30 days and next 180 days. Events from selected calendars are retained if a provider request fails. A successful switch to a different Apple account removes the previous account’s imports. Use Sync now after making changes in Apple Calendar; automatic background calendar refresh has not been enabled.</p><dl className="source-facts"><dt>Last successful calendar sync</dt><dd>{status?.lastSuccess ? `${formatDate(status.lastSuccess)} at ${time(status.lastSuccess)} London time` : "No successful calendar sync yet"}</dd>{status?.lastAttempt && <><dt>Last connection / sync attempt</dt><dd>{formatDate(status.lastAttempt)} at {time(status.lastAttempt)} London time</dd></>}</dl><button className="panel-link danger" disabled={busy} onClick={() => setConfirmDisconnect(true)}>Disconnect this Apple account</button></>}
    {confirmDisconnect && <div className="notice warning"><strong>Disconnect iCloud?</strong><p>This removes the saved encrypted Apple credentials. Your manually added Hub events are always kept.</p><label className="icloud-calendar-choice check-row"><input type="checkbox" checked={removeImported} disabled={busy} onChange={event => setRemoveImported(event.target.checked)}/><span>Also remove events imported from iCloud</span></label><div className="actions"><button className="button danger" disabled={busy} onClick={() => void disconnect()}>{busyAction === "disconnect" ? "Disconnecting…" : "Disconnect & remove credentials"}</button><button className="button ghost" disabled={busy} onClick={() => setConfirmDisconnect(false)}>Keep connected</button></div></div>}
    {busyAction && <p className="form-note" role="status">{busyAction === "connect" ? "Testing the supplied credentials with Apple before saving anything…" : busyAction === "sync" ? "Reading selected calendars and saving verified imported events…" : "Saving the private iCloud connection setting…"}</p>}
    {(requestError || status?.error) && <p className="error-text" role="alert">{requestError || status?.error}</p>}
    {message && <p className="notice success" role="status">{message}</p>}
    <button className="panel-link" disabled={busy} onClick={() => { setRequestError(""); void readStatus().then(() => refreshRef.current()).catch(error => setRequestError(error.message)); }}>Refresh saved connection status <Icon name="refresh" size={13}/></button>
  </div>;
}

/** Mounted only after wall query state is known and the household API confirms owner permission. */
function OwnerDashboardPreview() {
  const [loading, setLoading] = useState(true);
  const [result, setResult] = useState<Record<string, any> | null>(null);
  const [error, setError] = useState("");
  useEffect(() => {
    let active = true;
    const abort = new AbortController();
    void fetch("/api/admin", { credentials: "same-origin", cache: "no-store", signal: abort.signal }).then(async response => {
      const data: any = await response.json();
      if (!response.ok) throw new Error(data.error?.message || "The private weekly overview could not be read.");
      const reports = (data.results || []).filter((row: any) => /weekly.*dashboard|dashboard.*weekly/i.test(`${row.workflow || ""} ${row.title || ""}`)).sort((a: any, b: any) => String(b.observedAt || b.updatedAt || "").localeCompare(String(a.observedAt || a.updatedAt || "")));
      if (active) setResult(reports.find((row: any) => row.summary && row.lastSuccess) || reports[0] || null);
    }).catch(error => { if (active && error.name !== "AbortError") setError(error.message); }).finally(() => { if (active) setLoading(false); });
    return () => { active = false; abort.abort(); };
  }, []);
  const hasReport = !!result?.summary && !!result?.lastSuccess;
  const excerpt = result?.summary ? (result.summary.length > 900 ? result.summary.slice(0, 900).replace(/\s+\S*$/, "") + "…" : result.summary) : "";
  return <section className="panel owner-dashboard-preview"><div className="briefing-header"><span className="briefing-icon"><Icon name="lock" size={21}/></span><div><span className="panel-kicker">RYAN’S PRIVATE ADMIN</span><h2 className="panel-title">Your weekly dashboard</h2></div><span className="privacy-pill"><Icon name="lock" size={12}/> Ryan only</span></div>{loading ? <p className="subtle" role="status">Loading the latest saved private weekly overview…</p> : error ? <p className="error-text" role="alert">{error} The existing dashboard has not been treated as an empty task list.</p> : result ? <><div className="briefing-meta"><span className={`status-dot ${hasReport && result.lastSuccess ? freshness({ data: { lastSuccess: result.lastSuccess } }, Date.now()) : "grey"}`}/><span>{result.observedAt ? `${formatDate(result.observedAt)} · ${time(result.observedAt)} London` : "Report date not recorded"}</span><span className="briefing-status">{hasReport ? "Dated saved overview" : "Source access / report retrieval pending"}</span></div>{excerpt && <div className="briefing-summary"><ReportContent body={excerpt} originalUrl={result?.sourceLink}/></div>}{result.action && <div className="briefing-action"><strong>Next action</strong><p>{result.action}</p></div>}{!hasReport && <p className="form-note">The existing weekly dashboard is recognised. Its report has not yet been retrieved into this view; this does not mean there are no actions. The existing workflows keep their saved schedules.</p>}{safeLink(result.sourceLink) && <a className="panel-link" href={safeLink(result.sourceLink)} target="_blank" rel="noreferrer">Open existing dated dashboard <Icon name="arrow" size={14}/></a>}</> : <p className="subtle">No saved dashboard report is present in this preview yet. The existing dashboard still exists; use protected admin to inspect its latest imported result. This does not mean your task list is empty.</p>}<div className="briefing-footer"><span>Other admin records remain owner-only. The full dashboard you chose to share appears on the family wall.</span><a className="button ghost small" href="/admin">Open protected admin <Icon name="arrow" size={14}/></a></div></section>;
}
